import type { ConnectorEdge } from "./connectors.ts";
import type { HexCell } from "./hex.ts";
import type { RelationshipContext, RelationshipContextState } from "./relationshipContext.ts";
import type { SignalCellState, TopologySignal } from "./SignalEngine.ts";
import type { TopologyIconKey } from "./topologyIconRegistry.ts";

export type TopologyRenderVariant =
  | "root"
  | "anchor"
  | "cluster"
  | "entity"
  | "reference"
  | "primary"
  | "secondary"
  | "data";

export type TopologyRenderSize = "xs" | "sm" | "md" | "lg" | "xl" | "root";

export type TopologyGridCellStateKind = "idle" | "active" | "trail" | "converted";

export interface TopologyGridCellState {
  id: string;
  intensity: number;
  state: TopologyGridCellStateKind;
  type?: string;
}

export interface TopologyRenderOccupant {
  id: string;
  label: string;
  subtitle?: string;
  image?: string;
  icon?: TopologyIconKey;
  imageOffsetY?: number;
  imageScale?: number;
  imageAlign?: "center" | "top";
  q: number;
  r: number;
  href?: string;
  variant?: TopologyRenderVariant;
  size?: TopologyRenderSize;
  active?: boolean;
  selected?: boolean;
  disabled?: boolean;
}

export interface PreparedRenderOccupant extends TopologyRenderOccupant {
  cellId: string;
  relationshipState: RelationshipContextState | null;
}

export interface TopologyRenderRelationship extends ConnectorEdge {
  kind?: string;
  active?: boolean;
  muted?: boolean;
}

export type TopologyRenderLayerName =
  | "background"
  | "grid"
  | "relationships"
  | "occupants"
  | "signals"
  | "focus"
  | "labels";

export interface TopologyRenderLayer {
  name: TopologyRenderLayerName;
  order: number;
  count: number;
  enabled: boolean;
}

export interface TopologyRenderFrameInput {
  cells: HexCell[];
  occupants?: TopologyRenderOccupant[];
  relationships?: TopologyRenderRelationship[];
  signals?: TopologySignal[];
  signalStates?: Record<string, SignalCellState>;
  relationshipContext?: RelationshipContext | null;
  selectedId?: string | null;
  generatedAt?: number;
}

export interface TopologyRenderFrame {
  generatedAt: number;
  cells: HexCell[];
  occupants: PreparedRenderOccupant[];
  relationships: TopologyRenderRelationship[];
  signals: TopologySignal[];
  signalStates: Record<string, SignalCellState>;
  selectedId: string | null;
  relationshipContext: RelationshipContext | null;
  layers: TopologyRenderLayer[];
}

export const topologyRenderLayerOrder: readonly TopologyRenderLayerName[] = [
  "background",
  "grid",
  "relationships",
  "occupants",
  "signals",
  "focus",
  "labels",
];

function relationshipStateFor(
  entityId: string,
  context: RelationshipContext | null,
): RelationshipContextState | null {
  if (!context) return null;
  if (context.ancestorIds.includes(entityId)) return "ancestor";
  if (context.descendantIds.includes(entityId)) return "descendant";
  if (context.relatedIds.includes(entityId)) return "related";
  return null;
}

export function prepareTopologyRenderFrame({
  cells,
  occupants = [],
  relationships = [],
  signals = [],
  signalStates = {},
  relationshipContext = null,
  selectedId = null,
  generatedAt = Date.now(),
}: TopologyRenderFrameInput): TopologyRenderFrame {
  const visibleCellIds = new Set(cells.map((cell) => cell.id));
  const preparedOccupants = occupants
    .map((occupant) => ({
      ...occupant,
      cellId: `hex-${occupant.q}-${occupant.r}`,
      relationshipState: relationshipStateFor(occupant.id, relationshipContext),
    }))
    .filter((occupant) => visibleCellIds.has(occupant.cellId));
  const visibleOccupantIds = new Set(preparedOccupants.map((occupant) => occupant.id));
  const preparedRelationships = relationships.filter(
    (relationship) =>
      visibleOccupantIds.has(relationship.from) &&
      visibleOccupantIds.has(relationship.to),
  );
  const visibleSignalStates = Object.fromEntries(
    Object.entries(signalStates).filter(([cellId]) => visibleCellIds.has(cellId)),
  );
  const layerCounts: Record<TopologyRenderLayerName, number> = {
    background: 1,
    grid: cells.length,
    relationships: preparedRelationships.length,
    occupants: preparedOccupants.length,
    signals: Object.keys(visibleSignalStates).length || signals.length,
    focus: selectedId && visibleOccupantIds.has(selectedId) ? 1 : 0,
    labels: preparedOccupants.length,
  };

  return {
    generatedAt,
    cells: [...cells],
    occupants: preparedOccupants,
    relationships: preparedRelationships,
    signals: [...signals],
    signalStates: visibleSignalStates,
    selectedId,
    relationshipContext,
    layers: topologyRenderLayerOrder.map((name, order) => ({
      name,
      order,
      count: layerCounts[name],
      enabled: name === "background" || name === "grid" || layerCounts[name] > 0,
    })),
  };
}

export function summarizeTopologyRenderFrame(frame: TopologyRenderFrame) {
  return {
    generatedAt: frame.generatedAt,
    selectedId: frame.selectedId,
    visibleCells: frame.cells.length,
    visibleOccupants: frame.occupants.length,
    visibleRelationships: frame.relationships.length,
    activeSignals: frame.signals.length,
    layers: frame.layers.map((layer) => ({ ...layer })),
  };
}
